<?php require 'config.php'; require 'auth.php'; requireLogin(); $id=(int)($_GET['id']??0);$items=read_data('items');$idx=find_index($items,$id);if($idx!==null){array_splice($items,$idx,1);write_data('items',$items);$tx=array_values(array_filter(read_data('transactions'),fn($t)=>(int)$t['item_id']!==$id));write_data('transactions',$tx);$_SESSION['flash']=['type'=>'success','message'=>'Alat berhasil dihapus.'];}redirect('item_manage.php');